                for dc in range(min(len(fv[0]),len(dst[0]))):
                    if fv[dr][dc]: out[rb[dr]][c0_+dc]=fv[dr][dc]
    for ci,(ca,cb) in enumerate(zip(cg,cg[1:])):
        for ri,(ra,rb) in enumerate(zip(rg,rg[1:])):
